 "content": "def transform(grid):
    """Expand the central marker into a widening V and diagonal stripes."""
    n = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        # The two 2-colored arms expand one cell outward per row.
        for c in (center - r, center + r):
            if 0 <= c < n:
                out[r][c] = 2
        # Fill the wedge with the periodic down-right diagonal lattice.
        left, right = max(0, center - r), min(n - 1, center + r)
        for c in range(left, right + 1):
            if (c - r - center) % 4 == 0 and out[r][c] == 0:
                out[r][c] = 1
    return out
